<?php
require_once __DIR__ . '/_layout.php';requirePermission('deposits.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$deposit=dbFetchOne("SELECT d.*,r.reference FROM deposits d JOIN reservations r ON r.id=d.reservation_id WHERE d.id=? AND d.agency_id IN ($ph)",array_merge([$id],$ids));if(!$deposit){http_response_code(404);exit(t('validation.finance_not_found'));}
if(requestMethod()==='POST'){requireCsrfPost();try{$action=$_POST['action']??'';if($action==='event')appendDepositEvent(['deposit_id'=>$id,'event_type'=>$_POST['event_type']??'','amount'=>$_POST['amount']??'','method'=>$_POST['method']??'','reason'=>$_POST['reason']??'','idempotency_key'=>$_POST['idempotency_key']??'']);elseif($action==='resolve')resolveLegacyDepositOpening(['deposit_id'=>$id,'received_amount'=>$_POST['received_amount']??'','retained_amount'=>$_POST['retained_amount']??'','returned_amount'=>$_POST['returned_amount']??'','reason'=>$_POST['reason']??'','updated_at'=>$_POST['updated_at']??'','idempotency_key'=>$_POST['idempotency_key']??'']);else throw new InvalidArgumentException(t('validation.invalid_action'));flash('success',t('message.deposit_status_updated'));}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Deposit operation failed');flash('danger',t('message.finance_failed'));}safeRedirect('deposit_detail.php?id='.$id);}
$events=dbFetchAll('SELECT * FROM deposit_events WHERE deposit_id=:id ORDER BY occurred_at,id',['id'=>$id]);$unresolved=$deposit['legacy_opening_received_amount']===null||$deposit['legacy_opening_returned_amount']===null;backofficeHeader(t('page.deposit_detail.title'),'finance.php');pageHeader('page.deposit_detail.title','page.deposit_detail.description',['breadcrumbs'=>[['label'=>'nav.finance','href'=>'finance.php'],['label'=>$deposit['reference']]]]);?>
<div class="grid"><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=isolatedValue($deposit['reference'],'reference-value')?></h2></div><dl class="detail-list"><dt><?=e(t('field.requested'))?></dt><dd><?=money($deposit['amount'],$deposit['currency'])?></dd><dt><?=e(t('field.received'))?></dt><dd><?=$deposit['received_amount']===null?e(t('common.unresolved')):money($deposit['received_amount'],$deposit['currency'])?></dd><dt><?=e(t('field.retained'))?></dt><dd><?=money($deposit['retained_amount'],$deposit['currency'])?></dd><dt><?=e(t('field.returned'))?></dt><dd><?=$deposit['returned_amount']===null?e(t('common.unresolved')):money($deposit['returned_amount'],$deposit['currency'])?></dd><dt><?=e(t('common.status'))?></dt><dd><?=statusBadge($deposit['status'])?></dd></dl></section><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.deposit_events'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.number'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('field.reason'))?></th></tr></thead><tbody><?php foreach($events as$event):?><tr><td><?=isolatedValue($event['event_number'],'reference-value')?></td><td><?=e(t('deposit_event.'.$event['event_type']))?></td><td><?=money($event['amount'],$event['currency'])?></td><td><?=e($event['reason'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php if($unresolved):?><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.resolve_legacy_deposit'))?></h2></div><p><?=e(t('message.deposit_unresolved'))?></p><form method="post"><?=csrfField()?><?=financeIdempotencyField('deposit.resolve_legacy')?><input type="hidden" name="action" value="resolve"><input type="hidden" name="updated_at" value="<?=e($deposit['updated_at'])?>"><label><?=e(t('field.received'))?><input name="received_amount" required type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.retained'))?><input name="retained_amount" required type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.returned'))?><input name="returned_amount" required type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.reason'))?><input name="reason" required maxlength="255"></label><button class="btn primary"><?=e(t('action.resolve'))?></button></form></section><?php else:?><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.record_deposit_event'))?></h2></div><form method="post"><?=csrfField()?><?=financeIdempotencyField('deposit.event')?><input type="hidden" name="action" value="event"><label><?=e(t('field.type'))?><select name="event_type"><?php foreach(['received','held','partially_retained','fully_retained','partially_returned','returned']as$type):?><option value="<?=e($type)?>"><?=e(t('deposit_event.'.$type))?></option><?php endforeach;?></select></label><label><?=e(t('field.amount'))?><input name="amount" type="number" step="0.01" inputmode="decimal" value="0.00"></label><label><?=e(t('field.method'))?><select name="method"><?php foreach(financePaymentMethods()as$m):?><option value="<?=e($m)?>"><?=e(t('option.'.$m))?></option><?php endforeach;?></select></label><label><?=e(t('field.reason'))?><input name="reason" maxlength="255"></label><button class="btn primary"><?=e(t('action.record_deposit_event'))?></button></form></section><?php endif;?>
